-- Explicações por artigo — Lei dos Juizados Especiais Cíveis e Criminais (Lei nº 9.099, de 1995). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os Juizados Especiais Cíveis e Criminais, órgãos da Justiça Ordinária, serão criados pela União, no Distrito Federal e nos Territórios, e pelos Estados, para conciliação, processo, julgamento e execução, nas causas de sua competência.', '["Juizados Especiais Cíveis e Criminais são órgãos da Justiça Ordinária.","Criados pela União (DF e Territórios) e pelos Estados.","Conciliação, processo, julgamento e execução."]'::jsonb, '["Fazem parte da Justiça comum (ordinária), e não de justiça especializada."]'::jsonb, 'Cada Estado cria seus Juizados Especiais por lei.', '["Assertiva que classifica os Juizados como Justiça especializada erra: são órgãos da Justiça Ordinária."]'::jsonb, '[]'::jsonb, '["Art. 93"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo orientar-se-á pelos critérios da oralidade, simplicidade, informalidade, economia processual e celeridade, buscando, sempre que possível, a conciliação ou a transação.', '["Oralidade, simplicidade, informalidade, economia processual e celeridade.","Busca da conciliação ou da transação."]'::jsonb, '["Cinco critérios: oralidade, simplicidade, informalidade, economia processual e celeridade."]'::jsonb, 'O pedido pode ser feito oralmente à Secretaria do Juizado.', '["Assertiva que inclui a solenidade entre os critérios erra: o procedimento é informal."]'::jsonb, '[]'::jsonb, '["Art. 62"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade: as de valor até quarenta vezes o salário mínimo; as enumeradas no art. 275, inciso II, do antigo Código de Processo Civil; a ação de despejo para uso próprio; e as ações possessórias sobre imóveis de valor não excedente ao limite. Compete-lhe promover a execução dos seus julgados e dos títulos executivos extrajudiciais até quarenta vezes o salário mínimo. Ficam excluídas as causas de natureza alimentar, falimentar, fiscal e de interesse da Fazenda Pública, as relativas a acidentes de trabalho, a resíduos e ao estado e capacidade das pessoas. A opção pelo procedimento importa renúncia ao crédito excedente ao limite, salvo conciliação.', '["Teto: quarenta vezes o salário mínimo.","Despejo para uso próprio e ações possessórias de imóveis dentro do teto.","Execução dos julgados e de títulos extrajudiciais até o teto.","Exclusões: alimentar, falimentar, fiscal, Fazenda Pública, acidentes de trabalho, resíduos e estado e capacidade das pessoas.","Renúncia ao excedente, salvo conciliação."]'::jsonb, '["Teto de quarenta salários mínimos.","A opção pelo Juizado implica RENÚNCIA ao crédito excedente (exceto na conciliação)."]'::jsonb, 'Quem cobra vinte mil reais em dívida simples pode propor a ação no Juizado Especial.', '["Assertiva que permite ao Juizado Cível julgar causas de natureza fiscal erra: elas são excluídas."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É competente, para as causas da Lei, o Juizado do foro do domicílio do réu ou, a critério do autor, do local onde aquele exerça atividades profissionais ou econômicas ou mantenha estabelecimento, filial, agência, sucursal ou escritório; do lugar onde a obrigação deva ser satisfeita; e, nas ações para reparação de dano de qualquer natureza, do domicílio do autor ou do local do ato ou fato. Em qualquer hipótese, a ação poderá ser proposta no foro do domicílio do réu.', '["Domicílio do réu (ou local de atividade, a critério do autor).","Lugar do cumprimento da obrigação.","Reparação de dano: domicílio do autor ou local do fato.","O foro do réu sempre é possível."]'::jsonb, '["Na reparação de dano, o autor pode escolher o seu domicílio."]'::jsonb, 'Quem sofreu dano pode ajuizar a ação no Juizado do seu próprio domicílio.', '["Assertiva que fixa a competência apenas no domicílio do autor erra."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Juiz dirigirá o processo com liberdade para determinar as provas a serem produzidas, para apreciá-las e para dar especial valor às regras de experiência comum ou técnica.', '["Liberdade na direção do processo e na produção de provas.","Valor às regras de experiência comum ou técnica."]'::jsonb, '["Livre convencimento com regras de experiência."]'::jsonb, 'O juiz decide quais provas são úteis ao caso.', '["Assertiva que obriga o juiz a seguir rigidamente a prova tarifada erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Juiz adotará em cada caso a decisão que reputar mais justa e equânime, atendendo aos fins sociais da lei e às exigências do bem comum.', '["Decisão mais justa e equânime.","Fins sociais da lei e bem comum."]'::jsonb, '["Julgamento por equidade."]'::jsonb, 'O juiz decide com sensibilidade ao caso concreto, atendendo ao bem comum.', '["Assertiva que veda a equidade no Juizado erra."]'::jsonb, '[{"termo":"Equidade","significado":"Justiça aplicada ao caso concreto, com razoabilidade."}]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
