on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os conciliadores e Juízes leigos são auxiliares da Justiça, recrutados, os primeiros, preferentemente entre os bacharéis em Direito, e os segundos, entre advogados com mais de cinco anos de experiência. Os Juízes leigos ficarão impedidos de exercer a advocacia perante os Juizados Especiais enquanto no desempenho de suas funções.', '["Conciliadores: preferentemente bacharéis em Direito.","Juízes leigos: advogados com mais de cinco anos de experiência.","Juiz leigo não advoga nos Juizados enquanto exercer a função."]'::jsonb, '["Juiz leigo: advogado com mais de cinco anos."]'::jsonb, 'Um advogado com seis anos de experiência pode ser juiz leigo.', '["Assertiva que exige apenas dois anos de experiência para juiz leigo erra: são mais de cinco anos."]'::jsonb, '[{"termo":"Juiz leigo","significado":"Auxiliar da Justiça, advogado, que conduz a instrução e propõe a decisão."}]'::jsonb, '["Art. 37"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não poderão ser partes, no processo da Lei, o incapaz, o preso, as pessoas jurídicas de direito público, as empresas públicas da União, a massa falida e o insolvente civil. Somente serão admitidos a propor ação as pessoas físicas capazes, excluídos os cessionários de direito de pessoas jurídicas; as microempresas, empresas de pequeno porte e microempreendedores individuais; as Organizações da Sociedade Civil de Interesse Público; e as sociedades de crédito ao microempreendedor. O maior de dezoito anos poderá ser autor, independentemente de assistência, inclusive para fins de conciliação.', '["Não podem ser partes: incapaz, preso, pessoa jurídica de direito público, empresa pública da União, massa falida e insolvente civil.","Podem propor: pessoas físicas capazes, ME, EPP, MEI, OSCIP e sociedades de crédito ao microempreendedor.","Maior de dezoito anos pode ser autor sem assistência."]'::jsonb, '["ATUALIZAÇÃO: o §1º foi alterado por leis posteriores (microempresas e outras entidades como autoras).","O RÉU pode ser pessoa jurídica de direito privado; o que se veda é a pessoa jurídica de direito público como parte."]'::jsonb, 'A microempresa pode propor ação no Juizado Especial Cível.', '["Assertiva que permite ao preso ser parte no Juizado erra: ele não pode."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas causas de valor até vinte salários mínimos, as partes comparecerão pessoalmente, podendo ser assistidas por advogado; nas de valor superior, a assistência é obrigatória. Sendo facultativa a assistência, se uma das partes comparecer assistida por advogado, ou se o réu for pessoa jurídica ou firma individual, terá a outra parte, se quiser, assistência judiciária prestada por órgão instituído junto ao Juizado. O Juiz alertará as partes da conveniência do patrocínio por advogado. O mandato ao advogado poderá ser verbal, salvo quanto aos poderes especiais. O réu, sendo pessoa jurídica ou titular de firma individual, poderá ser representado por preposto credenciado, com carta de preposição e poderes para transigir, sem necessidade de vínculo empregatício.', '["Até vinte salários mínimos: advogado facultativo.","Acima de vinte: advogado obrigatório.","Mandato verbal, salvo poderes especiais.","Preposto credenciado, sem vínculo empregatício."]'::jsonb, '["Limite de vinte salários mínimos para a faculdade de advogado.","Preposto não precisa ser empregado."]'::jsonb, 'Em causa de dez salários mínimos, a parte pode ir sem advogado.', '["Assertiva que exige advogado em qualquer causa do Juizado erra: até vinte salários mínimos é facultativo."]'::jsonb, '[{"termo":"Preposto","significado":"Representante da empresa na audiência."}]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

