insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os atos processuais serão válidos sempre que preencherem as finalidades para as quais forem realizados. Não se pronunciará qualquer nulidade sem que tenha havido prejuízo. A prática de atos em outras comarcas poderá ser solicitada por qualquer meio idôneo. Apenas os atos essenciais serão registrados resumidamente, e os demais poderão ser gravados, a gravação sendo inutilizada após o trânsito em julgado. As normas locais disporão sobre a conservação das peças.', '["Validade pela finalidade do ato.","Sem nulidade sem prejuízo.","Atos em outras comarcas por qualquer meio idôneo.","Registro resumido dos atos essenciais; gravação dos demais."]'::jsonb, '["Princípio da instrumentalidade das formas e do prejuízo (pas de nullité sans grief)."]'::jsonb, 'A nulidade só é declarada se houver prejuízo comprovado.', '["Assertiva que decreta nulidade independentemente de prejuízo erra."]'::jsonb, '[]'::jsonb, '["Art. 65"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo instaurar-se-á com a apresentação do pedido, escrito ou oral, à Secretaria do Juizado. Do pedido constarão, de forma simples e em linguagem acessível, o nome, a qualificação e o endereço das partes; os fatos e os fundamentos, de forma sucinta; e o objeto e seu valor. É lícito formular pedido genérico quando não for possível determinar, desde logo, a extensão da obrigação. O pedido oral será reduzido a escrito pela Secretaria.', '["Pedido escrito ou oral à Secretaria.","Requisitos: partes, fatos e fundamentos sucintos, objeto e valor.","Pedido genérico quando não se pode determinar a extensão.","Pedido oral reduzido a escrito."]'::jsonb, '["O pedido pode ser ORAL."]'::jsonb, 'O autor vai à Secretaria e relata verbalmente o pedido, que é reduzido a escrito.', '["Assertiva que exige petição escrita assinada por advogado em todos os casos erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-14'
