insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os pedidos mencionados no art. 3º poderão ser alternativos ou cumulados; nesta última hipótese, desde que conexos e a soma não ultrapasse o limite fixado naquele dispositivo.', '["Pedidos alternativos ou cumulados.","Cumulação: conexos e dentro do limite do art. 3º."]'::jsonb, '["A soma dos pedidos não pode passar do teto."]'::jsonb, 'Dois pedidos conexos podem ser cumulados se a soma ficar dentro do teto.', '["Assertiva que permite cumular pedidos que ultrapassem o limite erra."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
