select u.id, u.content_sha256, 'Registrado o pedido, independentemente de distribuição e autuação, a Secretaria do Juizado designará a sessão de conciliação, a realizar-se no prazo de quinze dias.', '["Sessão de conciliação em quinze dias.","Independe de distribuição e autuação."]'::jsonb, '["Prazo de quinze dias."]'::jsonb, 'Após o registro do pedido, a conciliação é marcada em até quinze dias.', '["Assertiva que fixa em trinta dias o prazo da conciliação erra: são quinze."]'::jsonb, '[]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-16'
