insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comparecendo inicialmente ambas as partes, instaurar-se-á, desde logo, a sessão de conciliação, dispensados o registro prévio de pedido e a citação. Havendo pedidos contrapostos, poderá ser dispensada a contestação formal e ambos serão apreciados na mesma sentença.', '["Comparecimento de ambas as partes dispensa registro e citação.","Pedidos contrapostos: sem contestação formal, mesma sentença."]'::jsonb, '["Conciliação imediata quando ambas comparecem."]'::jsonb, 'Duas partes vão juntas ao Juizado e a conciliação ocorre na hora.', '["Assertiva que exige citação mesmo com ambas as partes presentes erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A citação far-se-á por correspondência, com aviso de recebimento em mão própria; tratando-se de pessoa jurídica ou firma individual, mediante entrega ao encarregado da recepção, que será obrigatoriamente identificado; ou, se necessário, por oficial de justiça, independentemente de mandado ou carta precatória. A citação conterá cópia do pedido inicial, dia e hora de comparecimento e advertência de que, não comparecendo o citando, considerar-se-ão verdadeiras as alegações iniciais e será proferido julgamento de plano. Não se fará citação por edital. O comparecimento espontâneo supre a falta ou nulidade da citação.', '["Citação por correspondência com aviso de recebimento em mão própria.","Pessoa jurídica: entrega ao encarregado da recepção, identificado.","Oficial de justiça, sem mandado ou precatória.","Vedada a citação por edital.","Comparecimento espontâneo supre a citação."]'::jsonb, '["NÃO cabe citação por edital."]'::jsonb, 'O réu não localizado leva à extinção do processo, pois não cabe edital.', '["Assertiva que admite a citação por edital no Juizado erra: ela é vedada."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-18'
