insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As intimações serão feitas na forma prevista para a citação, ou por qualquer outro meio idôneo. Dos atos praticados na audiência, consideram-se desde logo cientes as partes. As partes comunicarão ao juízo as mudanças de endereço, reputando-se eficazes as intimações enviadas ao endereço anterior na ausência de comunicação.', '["Intimação como a citação ou por meio idôneo.","Partes cientes dos atos da audiência.","Dever de comunicar mudança de endereço."]'::jsonb, '["Intimação no endereço antigo é eficaz se a mudança não foi comunicada."]'::jsonb, 'A parte que se mudou sem avisar o juízo é validamente intimada no endereço antigo.', '["Assertiva que invalida a intimação no endereço antigo mesmo sem comunicação da mudança erra."]'::jsonb, '[]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não comparecendo o demandado à sessão de conciliação ou à audiência de instrução e julgamento, reputar-se-ão verdadeiros os fatos alegados no pedido inicial, salvo se o contrário resultar da convicção do Juiz.', '["Revelia do réu: presunção de veracidade dos fatos.","Exceção: convicção contrária do juiz."]'::jsonb, '["A presunção de veracidade é relativa."]'::jsonb, 'O réu que não comparece tem os fatos do pedido presumidos verdadeiros.', '["Assertiva que torna a presunção absoluta, sem exceção, erra: o juiz pode formar convicção contrária."]'::jsonb, '[{"termo":"Revelia","significado":"Ausência do réu, com presunção de veracidade dos fatos alegados."}]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-20'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aberta a sessão, o Juiz togado ou leigo esclarecerá as partes presentes sobre as vantagens da conciliação, mostrando-lhes os riscos e as consequências do litígio, especialmente quanto ao disposto no §3º do art. 3º da Lei.', '["Esclarecimento das vantagens da conciliação.","Alerta sobre os riscos do litígio e a renúncia ao excedente."]'::jsonb, '["Dever de esclarecer, em especial sobre a renúncia ao crédito excedente."]'::jsonb, 'O juiz explica ao autor que, sem conciliar, renuncia ao valor acima do teto.', '["Assertiva que dispensa o esclarecimento sobre as consequências do litígio erra."]'::jsonb, '[]'::jsonb, '["Art. 3º, §3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-21'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A conciliação será conduzida pelo Juiz togado ou leigo ou por conciliador sob sua orientação. Obtida a conciliação, será reduzida a escrito e homologada pelo Juiz togado mediante sentença com eficácia de título executivo. É cabível a conciliação não presencial, conduzida pelo Juizado por recursos tecnológicos de transmissão de sons e imagens em tempo real, com o resultado reduzido a escrito.', '["Conduzida pelo juiz, juiz leigo ou conciliador.","Homologação pelo juiz togado, com eficácia de título executivo.","Conciliação não presencial por som e imagem."]'::jsonb, '["ATUALIZAÇÃO: o §2º (conciliação não presencial) foi incluído pela Lei nº 13.994, de 2020.","Quem homologa é o juiz TOGADO."]'::jsonb, 'A conciliação ocorre por videoconferência, e o acordo é homologado pelo juiz.', '["Assertiva que permite ao conciliador homologar o acordo erra: a homologação é do juiz togado."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o demandado não comparecer ou recusar-se a participar da tentativa de conciliação não presencial, o Juiz togado proferirá sentença.', '["Ausência ou recusa do réu na conciliação não presencial leva à sentença."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 13.994, de 2020."]'::jsonb, 'O réu que não participa da conciliação virtual sofre sentença do juiz togado.', '["Assertiva que dispensa a sentença em caso de ausência do réu erra."]'::jsonb, '[]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
