insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não obtida a conciliação, as partes poderão optar, de comum acordo, pelo juízo arbitral, na forma da Lei. O juízo arbitral considerar-se-á instaurado, independentemente de termo de compromisso, com a escolha do árbitro pelas partes, e se este não estiver presente o Juiz o convocará e designará, de imediato, a data da audiência de instrução. O árbitro será escolhido dentre os juízes leigos.', '["Arbitragem por comum acordo, após a conciliação frustrada.","Instaurada com a escolha do árbitro, sem termo de compromisso.","Árbitro escolhido entre os juízes leigos."]'::jsonb, '["Árbitro: sempre juiz LEIGO."]'::jsonb, 'As partes escolhem um juiz leigo como árbitro.', '["Assertiva que exige termo de compromisso para instaurar a arbitragem no Juizado erra."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

