select u.id, u.content_sha256, 'Ao término da instrução, ou nos cinco dias subsequentes, o árbitro apresentará o laudo ao Juiz togado para homologação por sentença irrecorrível.', '["Laudo arbitral em até cinco dias após a instrução.","Homologação por sentença irrecorrível."]'::jsonb, '["Sentença homologatória IRRECORRÍVEL."]'::jsonb, 'O laudo do árbitro é homologado e não comporta recurso.', '["Assertiva que admite recurso contra a homologação do laudo arbitral erra: ela é irrecorrível."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
