insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não instituído o juízo arbitral, proceder-se-á imediatamente à audiência de instrução e julgamento, desde que não resulte prejuízo para a defesa. Não sendo possível a realização imediata, a audiência será designada para um dos quinze dias subsequentes, cientes desde logo as partes e testemunhas presentes.', '["Audiência de instrução e julgamento imediata, sem prejuízo à defesa.","Se não for possível, em até quinze dias."]'::jsonb, '["Prazo de quinze dias para a audiência, se não imediata."]'::jsonb, 'Frustrada a conciliação, a audiência é marcada para os quinze dias seguintes.', '["Assertiva que fixa em trinta dias o prazo da audiência erra: são quinze dias."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-27'
