select u.id, u.content_sha256, 'Na audiência de instrução e julgamento serão ouvidas as partes, colhida a prova e, em seguida, proferida a sentença.', '["Oitiva das partes, colheita da prova e sentença na mesma audiência."]'::jsonb, '["Concentração dos atos."]'::jsonb, 'Na mesma audiência o juiz ouve as partes e profere a sentença.', '["Assertiva que separa a instrução do julgamento em audiências distintas obrigatoriamente erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-28'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Serão decididos de plano todos os incidentes que possam interferir no regular prosseguimento da audiência. As demais questões serão decididas na sentença. Sobre os documentos apresentados por uma das partes, manifestar-se-á imediatamente a parte contrária, sem interrupção da audiência.', '["Incidentes decididos de plano.","Demais questões na sentença.","Manifestação imediata sobre documentos."]'::jsonb, '["Agilidade: sem interrupção da audiência."]'::jsonb, 'O juiz decide na hora o incidente que atrapalha a audiência.', '["Assertiva que suspende a audiência para a manifestação sobre documentos erra: ela é imediata."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-29'
