insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A contestação, que será oral ou escrita, conterá toda matéria de defesa, exceto a arguição de suspeição ou impedimento do Juiz, que se processará na forma da legislação em vigor.', '["Contestação oral ou escrita.","Toda a matéria de defesa.","Exceção: suspeição e impedimento do juiz."]'::jsonb, '["Contestação pode ser oral."]'::jsonb, 'O réu contesta oralmente na audiência.', '["Assertiva que exige contestação sempre escrita erra: ela pode ser oral."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-30'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não se admitirá a reconvenção. É lícito ao réu, na contestação, formular pedido em seu favor, nos limites do art. 3º, desde que fundado nos mesmos fatos que constituem objeto da controvérsia. O autor poderá responder ao pedido do réu na própria audiência ou requerer a designação de nova data, desde logo fixada.', '["Sem reconvenção.","Pedido contraposto na contestação, dentro do teto e com base nos mesmos fatos.","Resposta do autor na audiência ou em nova data."]'::jsonb, '["NÃO há reconvenção, mas há PEDIDO CONTRAPOSTO."]'::jsonb, 'O réu pede, na contestação, indenização com base nos mesmos fatos.', '["Assertiva que admite a reconvenção no Juizado erra: admite-se o pedido contraposto."]'::jsonb, '[{"termo":"Pedido contraposto","significado":"Pedido do réu contra o autor, na própria contestação."}]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-31'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

