select u.id, u.content_sha256, 'Todos os meios de prova moralmente legítimos, ainda que não especificados em lei, são hábeis para provar a veracidade dos fatos alegados pelas partes.', '["Todos os meios de prova moralmente legítimos, mesmo não previstos em lei."]'::jsonb, '["Liberdade de prova limitada pela legitimidade moral."]'::jsonb, 'Uma gravação lícita pode ser usada como prova.', '["Assertiva que restringe as provas aos meios previstos em lei erra."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
