insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todas as provas serão produzidas na audiência de instrução e julgamento, ainda que não requeridas previamente, podendo o Juiz limitar ou excluir as que considerar excessivas, impertinentes ou protelatórias.', '["Provas produzidas na audiência, ainda que não requeridas antes.","Juiz pode limitar ou excluir as excessivas, impertinentes ou protelatórias."]'::jsonb, '["Concentração das provas na audiência."]'::jsonb, 'O juiz dispensa a prova que apenas protelaria o processo.', '["Assertiva que exige o requerimento prévio de todas as provas erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
