insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As testemunhas, até o máximo de três para cada parte, comparecerão à audiência levadas pela parte que as arrolou, independentemente de intimação, ou mediante esta, se requerido. O requerimento de intimação será apresentado à Secretaria no mínimo cinco dias antes da audiência. Não comparecendo a testemunha intimada, o Juiz poderá determinar sua imediata condução, valendo-se, se necessário, da força pública.', '["No máximo três testemunhas por parte.","A parte leva as testemunhas, ou pede a intimação cinco dias antes.","Condução coercitiva da testemunha intimada que falta."]'::jsonb, '["Máximo de três testemunhas por parte."]'::jsonb, 'Cada parte pode levar até três testemunhas.', '["Assertiva que fixa em cinco o número máximo de testemunhas por parte erra: são três."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
