insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a prova do fato exigir, o Juiz poderá inquirir técnicos de sua confiança, permitida às partes a apresentação de parecer técnico. No curso da audiência, poderá o Juiz, de ofício ou a requerimento das partes, realizar inspeção em pessoas ou coisas, ou determinar que o faça pessoa de sua confiança, que lhe relatará informalmente o verificado.', '["Inquirição de técnicos de confiança do juiz.","Parecer técnico das partes.","Inspeção em pessoas ou coisas, com relato informal."]'::jsonb, '["Não há perícia formal: o juiz ouve técnicos."]'::jsonb, 'O juiz ouve um técnico de sua confiança sobre o defeito do produto.', '["Assertiva que exige perícia formal nos Juizados erra: o juiz pode inquirir técnicos."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
