select u.id, u.content_sha256, 'O Juiz leigo que tiver dirigido a instrução proferirá sua decisão e imediatamente a submeterá ao Juiz togado, que poderá homologá-la, proferir outra em substituição ou, antes de se manifestar, determinar a realização de atos probatórios indispensáveis.', '["Juiz leigo decide e submete ao togado.","Togado homologa, substitui ou manda produzir provas."]'::jsonb, '["A decisão do leigo depende do togado."]'::jsonb, 'O juiz togado homologa a decisão elaborada pelo juiz leigo.', '["Assertiva que dispensa a homologação do juiz togado erra."]'::jsonb, '[]'::jsonb, '["Art. 37"]'::jsonb, 'under_review', 'claude'
