insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Da sentença, excetuada a homologatória de conciliação ou laudo arbitral, caberá recurso para o próprio Juizado. O recurso será julgado por uma turma composta por três juízes togados, em exercício no primeiro grau de jurisdição, reunidos na sede do Juizado. No recurso, as partes serão obrigatoriamente representadas por advogado.', '["Recurso para o próprio Juizado (turma recursal).","Turma de três juízes togados de primeiro grau.","Não cabe contra sentença homologatória de conciliação ou laudo.","Advogado obrigatório no recurso."]'::jsonb, '["Advogado OBRIGATÓRIO no recurso.","A turma é composta por juízes de primeiro grau."]'::jsonb, 'O recurso contra a sentença vai à Turma Recursal, com advogado.', '["Assertiva que permite o recurso sem advogado erra: é obrigatório."]'::jsonb, '[{"termo":"Turma Recursal","significado":"Órgão do próprio Juizado que julga os recursos."}]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-41'
