select u.id, u.content_sha256, 'Os embargos de declaração interrompem o prazo para a interposição de recurso.', '["Interrupção do prazo para recurso."]'::jsonb, '["INTERROMPEM (e não apenas suspendem) o prazo."]'::jsonb, 'Opostos os embargos, o prazo do recurso recomeça por inteiro.', '["Assertiva que apenas suspende o prazo do recurso com os embargos erra: o prazo é interrompido."]'::jsonb, '[]'::jsonb, '["Art. 49"]'::jsonb, 'under_review', 'claude'
