insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Extingue-se o processo, além dos casos previstos em lei, quando o autor deixar de comparecer a qualquer das audiências; quando inadmissível o procedimento ou seu prosseguimento após a conciliação; quando reconhecida a incompetência territorial; quando sobrevier qualquer dos impedimentos do art. 8º; quando, falecido o autor, a habilitação depender de sentença ou não se der em trinta dias; e quando, falecido o réu, o autor não promover a citação dos sucessores em trinta dias da ciência do fato. A extinção independe de prévia intimação pessoal das partes. No caso de ausência do autor, se provar força maior, poderá ser isentado das custas.', '["Ausência do autor em qualquer audiência.","Procedimento inadmissível.","Incompetência territorial.","Impedimentos do art. 8º.","Morte do autor ou do réu sem habilitação ou citação dos sucessores em trinta dias."]'::jsonb, '["A ausência do AUTOR extingue o processo; a do RÉU gera revelia.","A extinção independe de intimação pessoal."]'::jsonb, 'O autor falta à audiência e o processo é extinto.', '["Assertiva que exige intimação pessoal prévia para extinguir o processo erra."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-51'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A execução da sentença processar-se-á no próprio Juizado, aplicando-se, no que couber, o Código de Processo Civil, com alterações: as sentenças serão necessariamente líquidas; os cálculos serão feitos por servidor judicial; a intimação da sentença será feita na própria audiência, advertido o vencido dos efeitos do descumprimento; não cumprida a sentença transitada em julgado, procede-se à execução a pedido, que pode ser verbal, sem nova citação; e, nas obrigações de entregar, fazer ou não fazer, o juiz cominará multa diária, que pode ser elevada ou convertida em perdas e danos.', '["Execução no próprio Juizado.","Sentenças líquidas.","Cálculos por servidor judicial.","Execução a pedido, que pode ser verbal, sem nova citação.","Multa diária nas obrigações de fazer, não fazer e entregar."]'::jsonb, '["Execução dispensa nova citação.","O pedido de execução pode ser VERBAL."]'::jsonb, 'O credor pede verbalmente a execução da sentença não cumprida.', '["Assertiva que exige nova citação do devedor na execução erra."]'::jsonb, '[]'::jsonb, '["Art. 53"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-52'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A execução de título executivo extrajudicial, no valor de até quarenta salários mínimos, obedecerá ao Código de Processo Civil, com as modificações da Lei. Efetuada a penhora, o devedor será intimado a comparecer à audiência de conciliação, quando poderá oferecer embargos, por escrito ou verbalmente. Na audiência, será buscado o meio mais rápido e eficaz de solução, se possível com dispensa da alienação judicial, propondo-se pagamento a prazo, dação em pagamento ou adjudicação. Não apresentados ou improcedentes os embargos, qualquer parte poderá pedir uma das alternativas. Não encontrado o devedor ou inexistindo bens penhoráveis, o processo será imediatamente extinto.', '["Execução de título extrajudicial até quarenta salários mínimos.","Audiência de conciliação após a penhora.","Embargos orais ou escritos.","Alternativas: pagamento parcelado, dação em pagamento ou adjudicação.","Extinção se não houver devedor ou bens."]'::jsonb, '["Execução de título extrajudicial: teto de quarenta salários mínimos."]'::jsonb, 'A execução de um cheque até o teto segue o rito do Juizado.', '["Assertiva que fixa em sessenta salários mínimos o teto da execução extrajudicial no Juizado erra: são quarenta."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-53'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O acesso ao Juizado Especial independerá, em primeiro grau de jurisdição, do pagamento de custas, taxas ou despesas. O preparo do recurso compreenderá todas as despesas processuais, inclusive aquelas dispensadas em primeiro grau, ressalvada a assistência judiciária gratuita.', '["Gratuidade em primeiro grau.","Preparo do recurso inclui todas as despesas."]'::jsonb, '["Gratuito em primeiro grau; pago no recurso."]'::jsonb, 'O autor não paga custas na petição inicial, mas paga o preparo para recorrer.', '["Assertiva que isenta o recorrente de qualquer despesa no recurso erra: o preparo compreende todas as despesas."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-54'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença de primeiro grau não condenará o vencido em custas e honorários de advogado, ressalvados os casos de litigância de má-fé. Em segundo grau, o recorrente vencido pagará as custas e honorários de advogado, fixados entre dez por cento e vinte por cento do valor de condenação ou, não havendo condenação, do valor corrigido da causa. Na execução não serão contadas custas, salvo se reconhecida a litigância de má-fé, improcedentes os embargos do devedor ou em execução de sentença cujo recurso do devedor foi improvido.', '["Sem condenação em custas e honorários em primeiro grau, salvo má-fé.","Em segundo grau, o recorrente vencido paga custas e honorários de dez a vinte por cento.","Sem custas na execução, salvo exceções."]'::jsonb, '["Honorários em segundo grau: de dez por cento a vinte por cento."]'::jsonb, 'O recorrente que perde o recurso paga honorários de dez a vinte por cento.', '["Assertiva que condena o vencido em honorários em primeiro grau, sem má-fé, erra."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
