insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O acordo extrajudicial, de qualquer natureza ou valor, poderá ser homologado, no juízo competente, independentemente de termo, valendo a sentença como título executivo judicial. Valerá como título extrajudicial o acordo celebrado pelas partes, por instrumento escrito, referendado pelo órgão competente do Ministério Público.', '["Acordo extrajudicial de qualquer valor pode ser homologado.","Sentença homologatória é título executivo judicial.","Acordo referendado pelo Ministério Público é título extrajudicial."]'::jsonb, '["Acordo extrajudicial homologado: título JUDICIAL; referendado pelo MP: título EXTRAJUDICIAL."]'::jsonb, 'O acordo firmado fora do processo é homologado e passa a ser título judicial.', '["Assertiva que limita a homologação aos acordos até o teto do Juizado erra: vale para qualquer natureza ou valor."]'::jsonb, '[]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
