select u.id, u.content_sha256, 'As normas de organização judiciária local poderão estender a conciliação prevista nos arts. 22 e 23 a causas não abrangidas por esta Lei.', '["Extensão da conciliação a causas fora da Lei."]'::jsonb, '["Possibilidade por norma local."]'::jsonb, 'Uma lei estadual estende a conciliação a causas mais complexas.', '["Assertiva que veda qualquer extensão da conciliação erra."]'::jsonb, '[]'::jsonb, '["Arts. 22 e 23"]'::jsonb, 'under_review', 'claude'
