select u.id, u.content_sha256, 'Não se admitirá ação rescisória nas causas sujeitas ao procedimento instituído por esta Lei.', '["Vedada a ação rescisória."]'::jsonb, '["NÃO cabe ação rescisória nos Juizados."]'::jsonb, 'A sentença transitada em julgado do Juizado não pode ser desfeita por rescisória.', '["Assertiva que admite ação rescisória no Juizado erra: é vedada."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
