insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Juizado Especial Criminal, provido por juízes togados ou togados e leigos, tem competência para a conciliação, o julgamento e a execução das infrações penais de menor potencial ofensivo, respeitadas as regras de conexão e continência. Na reunião de processos perante o juízo comum ou o tribunal do júri, decorrentes das regras de conexão e continência, observar-se-ão os institutos da transação penal e da composição dos danos civis.', '["Competência: infrações de menor potencial ofensivo.","Conciliação, julgamento e execução.","Conexão e continência respeitadas.","Transação penal e composição civil preservadas na reunião de processos."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 11.313, de 2006.","Mesmo na reunião de processos no júri ou no juízo comum, aplicam-se transação e composição."]'::jsonb, 'O crime de menor potencial ofensivo é julgado no Juizado Criminal.', '["Assertiva que afasta a transação penal quando há reunião de processos no juízo comum erra."]'::jsonb, '[]'::jsonb, '["Art. 61"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-60'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Consideram-se infrações penais de menor potencial ofensivo, para os efeitos desta Lei, as contravenções penais e os crimes a que a lei comine pena máxima não superior a 2 anos, cumulada ou não com multa.', '["Contravenções penais.","Crimes com pena máxima não superior a 2 anos."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 11.313, de 2006 (antes eram um ano; hoje, dois anos).","Limite: pena MÁXIMA não superior a 2 anos, e não a pena mínima.","Vale para a Justiça Estadual e para a Federal."]'::jsonb, 'Um crime com pena máxima de dois anos é infração de menor potencial ofensivo.', '["Assertiva que fixa em um ano a pena máxima das infrações de menor potencial ofensivo erra: são 2 anos."]'::jsonb, '[{"termo":"Infração de menor potencial ofensivo","significado":"Contravenção ou crime com pena máxima não superior a 2 anos."}]'::jsonb, '["Art. 60"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-61'
