insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo perante o Juizado Especial Criminal orientar-se-á pelos critérios da oralidade, simplicidade, informalidade, economia processual e celeridade, objetivando, sempre que possível, a reparação dos danos sofridos pela vítima e a aplicação de pena não privativa de liberdade.', '["Oralidade, simplicidade, informalidade, economia processual e celeridade.","Reparação do dano à vítima.","Pena não privativa de liberdade."]'::jsonb, '["Prioriza a reparação e as penas alternativas."]'::jsonb, 'O Juizado busca primeiro a composição dos danos e a pena alternativa.', '["Assertiva que prioriza a prisão no Juizado Criminal erra: a pena não privativa de liberdade é prioritária."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-62'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A competência do Juizado será determinada pelo lugar em que foi praticada a infração penal.', '["Competência pelo lugar da infração."]'::jsonb, '["Critério do lugar da INFRAÇÃO (teoria da atividade)."]'::jsonb, 'A infração praticada em certa cidade é julgada pelo Juizado dali.', '["Assertiva que fixa a competência pelo domicílio do autor do fato erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
