insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os atos processuais serão válidos sempre que preencherem as finalidades para as quais foram realizados. Não se pronunciará qualquer nulidade sem que tenha havido prejuízo. A prática de atos em outras comarcas poderá ser solicitada por qualquer meio hábil. Serão objeto de registro escrito exclusivamente os atos essenciais, e os realizados em audiência de instrução e julgamento poderão ser gravados.', '["Validade pela finalidade.","Sem nulidade sem prejuízo.","Registro escrito só dos atos essenciais.","Gravação dos atos da audiência."]'::jsonb, '["Mesmo princípio da instrumentalidade e do prejuízo no âmbito criminal."]'::jsonb, 'Só se anula o ato que causar prejuízo.', '["Assertiva que decreta nulidade sem prejuízo erra."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
