insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A citação será pessoal e far-se-á no próprio Juizado, sempre que possível, ou por mandado. Não encontrado o acusado para ser citado, o Juiz encaminhará as peças existentes ao Juízo comum para adoção do procedimento previsto em lei.', '["Citação pessoal, no Juizado ou por mandado.","Acusado não encontrado: remessa ao juízo comum."]'::jsonb, '["Não há citação por edital no Juizado Criminal; o caso vai ao juízo comum."]'::jsonb, 'Se o acusado não é localizado, o processo segue para a vara criminal comum.', '["Assertiva que admite a citação por edital no Juizado Criminal erra: o caso vai ao juízo comum."]'::jsonb, '[]'::jsonb, '["Art. 77"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-66'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A intimação far-se-á por correspondência, com aviso de recebimento pessoal ou, tratando-se de pessoa jurídica ou firma individual, mediante entrega ao encarregado da recepção, que será obrigatoriamente identificado, ou, sendo necessário, por oficial de justiça, independentemente de mandado ou carta precatória, ou ainda por qualquer meio idôneo de comunicação. Dos atos praticados em audiência, consideram-se desde logo cientes as partes, os interessados e defensores.', '["Intimação por correspondência, oficial de justiça ou meio idôneo.","Ciência imediata dos atos praticados em audiência."]'::jsonb, '["Quem está na audiência já fica ciente."]'::jsonb, 'A data da próxima audiência é informada na própria audiência.', '["Assertiva que exige nova intimação para atos praticados em audiência erra: todos já ficam cientes."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-67'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Do ato de intimação do autor do fato e do mandado de citação do acusado, constará a necessidade de seu comparecimento acompanhado de advogado, com a advertência de que, na sua falta, ser-lhe-á designado defensor público.', '["Comparecimento acompanhado de advogado.","Defensor público designado se não tiver advogado."]'::jsonb, '["A defesa técnica é obrigatória."]'::jsonb, 'O acusado sem advogado recebe defensor público.', '["Assertiva que dispensa advogado ou defensor para o acusado no Juizado Criminal erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-68'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade policial que tomar conhecimento da ocorrência lavrará termo circunstanciado e o encaminhará imediatamente ao Juizado, com o autor do fato e a vítima, providenciando as requisições dos exames periciais necessários. Ao autor do fato que, após a lavratura do termo, for imediatamente encaminhado ao Juizado ou assumir o compromisso de a ele comparecer, não se imporá prisão em flagrante, nem se exigirá fiança. Em caso de violência doméstica, o juiz poderá determinar, como medida de cautela, seu afastamento do lar, domicílio ou local de convivência com a vítima.', '["Termo circunstanciado de ocorrência (TCO) em vez de inquérito.","Encaminhamento imediato ao Juizado.","Sem prisão em flagrante nem fiança se comparecer ou assumir o compromisso.","Afastamento do lar em violência doméstica."]'::jsonb, '["ATUALIZAÇÃO: redação do parágrafo único alterada por leis posteriores, inclusive a Lei Maria da Penha.","TCO substitui o inquérito."]'::jsonb, 'A polícia lavra termo circunstanciado e encaminha o autor ao Juizado, sem prendê-lo.', '["Assertiva que exige prisão em flagrante e fiança para quem assume o compromisso de comparecer erra."]'::jsonb, '[{"termo":"TCO","significado":"Termo circunstanciado de ocorrência, registro simplificado do fato."}]'::jsonb, '["Art. 77"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-69'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comparecendo o autor do fato e a vítima, e não sendo possível a realização imediata da audiência preliminar, será designada data próxima, da qual ambos sairão cientes.', '["Audiência preliminar em data próxima, se não for imediata."]'::jsonb, '["Ambos saem cientes da data."]'::jsonb, 'A audiência preliminar é marcada para a semana seguinte, e as partes saem intimadas.', '["Assertiva que exige nova intimação por correspondência nesse caso erra: ambos saem cientes."]'::jsonb, '[]'::jsonb, '["Art. 72"]'::jsonb, 'under_review', 'claude'
