insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na falta do comparecimento de qualquer dos envolvidos, a Secretaria providenciará sua intimação e, se for o caso, a do responsável civil, na forma dos arts. 67 e 68 da Lei.', '["Intimação do ausente e do responsável civil."]'::jsonb, '["A Secretaria providencia a intimação."]'::jsonb, 'Se a vítima falta, a Secretaria a intima novamente.', '["Assertiva que extingue o processo pela ausência da vítima à primeira audiência erra: providencia-se a intimação."]'::jsonb, '[]'::jsonb, '["Arts. 67 e 68"]'::jsonb, 'under_review', 'claude'
