insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na audiência preliminar, presente o representante do Ministério Público, o autor do fato e a vítima e, se possível, o responsável civil, acompanhados de seus advogados, o Juiz esclarecerá sobre a possibilidade da composição dos danos e da aceitação da proposta de aplicação imediata de pena não privativa de liberdade.', '["Audiência preliminar com MP, autor, vítima e advogados.","Esclarecimento sobre composição dos danos e transação penal."]'::jsonb, '["Primeira fase: composição civil; depois, transação penal."]'::jsonb, 'O juiz explica ao autor do fato as possibilidades de composição e de transação.', '["Assertiva que dispensa a presença do Ministério Público na audiência preliminar erra."]'::jsonb, '[]'::jsonb, '["Art. 74","Art. 76"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-72'
