insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A conciliação será conduzida pelo Juiz ou por conciliador sob sua orientação. Os conciliadores são auxiliares da Justiça, recrutados, na forma da lei local, preferentemente entre bacharéis em Direito, excluídos os que exerçam funções na administração da Justiça Criminal.', '["Conciliação pelo juiz ou por conciliador.","Conciliadores: preferentemente bacharéis em Direito.","Excluídos os que atuam na administração da Justiça Criminal."]'::jsonb, '["Vedados os que exercem funções na Justiça Criminal."]'::jsonb, 'Um bacharel em Direito atua como conciliador no Juizado Criminal.', '["Assertiva que permite a delegado atuar como conciliador erra: os que exercem funções na administração da Justiça Criminal são excluídos."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
