on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A composição dos danos civis será reduzida a escrito e, homologada pelo Juiz mediante sentença irrecorrível, terá eficácia de título a ser executado no juízo civil competente. Tratando-se de ação penal de iniciativa privada ou de ação penal pública condicionada à representação, o acordo homologado acarreta a renúncia ao direito de queixa ou representação.', '["Composição civil homologada por sentença irrecorrível, com eficácia de título.","Execução no juízo civil.","Em ação privada ou condicionada, o acordo importa renúncia à queixa ou representação."]'::jsonb, '["Composição civil NÃO extingue a punibilidade nos crimes de ação pública incondicionada."]'::jsonb, 'Na ação condicionada à representação, o acordo homologado impede que a vítima represente depois.', '["Assertiva que não vê efeito penal na composição civil em ação privada erra: ela acarreta renúncia ao direito de queixa."]'::jsonb, '[]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-74'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não obtida a composição dos danos civis, será dada imediatamente ao ofendido a oportunidade de exercer o direito de representação verbal, que será reduzida a termo. O não oferecimento da representação na audiência preliminar não implica decadência do direito, que poderá ser exercido no prazo previsto em lei.', '["Representação verbal, reduzida a termo.","Não representar na audiência não gera decadência."]'::jsonb, '["A representação pode ser oferecida depois, no prazo legal."]'::jsonb, 'A vítima não representa na audiência, mas ainda pode fazê-lo dentro do prazo.', '["Assertiva que decreta decadência se a vítima não representa na audiência erra."]'::jsonb, '[]'::jsonb, '["Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-75'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transação penal: havendo representação ou tratando-se de crime de ação penal pública incondicionada, não sendo caso de arquivamento, o Ministério Público poderá propor a aplicação imediata de pena restritiva de direitos ou multas. Se a multa for a única pena aplicável, o juiz poderá reduzi-la até a metade. Não se admite a proposta se o autor foi condenado, por crime, a pena privativa de liberdade por sentença definitiva; se foi beneficiado nos cinco anos anteriores por transação; ou se os antecedentes, a conduta social e a personalidade, os motivos e as circunstâncias não indicarem ser a medida necessária e suficiente. Aceita a proposta pelo autor e seu defensor, será apreciada pelo juiz, que aplicará a pena, sem reincidência, apenas registrada para impedir novo benefício em cinco anos. Da sentença cabe apelação.', '["Proposta do Ministério Público de pena restritiva de direitos ou multa.","Vedada se houve condenação a pena privativa de liberdade, benefício nos cinco anos anteriores ou circunstâncias desfavoráveis.","Aceitação pelo autor e pelo defensor.","Sem reincidência; registro só para impedir novo benefício em cinco anos.","Apelação cabível."]'::jsonb, '["Cinco anos de intervalo entre transações.","Não gera reincidência nem maus antecedentes, mas impede novo benefício por cinco anos.","É um direito subjetivo do réu, segundo a jurisprudência, se preenchidos os requisitos."]'::jsonb, 'O Ministério Público propõe multa ao autor de uma ameaça, que aceita e não responde a processo.', '["Assertiva que considera reincidente quem aceita a transação penal erra: ela não importa em reincidência."]'::jsonb, '[{"termo":"Transação penal","significado":"Acordo em que o autor aceita pena alternativa imediata, sem processo."}]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-76'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na ação penal de iniciativa pública, quando não houver aplicação de pena, pela ausência do autor do fato ou pela não ocorrência da hipótese do art. 76, o Ministério Público oferecerá ao Juiz, de imediato, denúncia oral, se não houver necessidade de diligências imprescindíveis. A denúncia será elaborada com base no termo de ocorrência, com dispensa do inquérito policial, prescindindo-se do exame de corpo de delito quando a materialidade estiver aferida por boletim médico ou prova equivalente. Se a complexidade do caso não permitir, o Ministério Público poderá requerer o encaminhamento das peças ao juízo comum. Na ação de iniciativa do ofendido poderá ser oferecida queixa oral.', '["Denúncia oral, se não houver transação.","Com base no termo circunstanciado, dispensado o inquérito.","Dispensa do exame de corpo de delito com boletim médico.","Caso complexo: remessa ao juízo comum.","Queixa oral na ação privada."]'::jsonb, '["Denúncia ORAL, com dispensa do inquérito policial."]'::jsonb, 'O Promotor oferece denúncia oral logo após a frustração da transação penal.', '["Assertiva que exige inquérito policial prévio para a denúncia no Juizado erra: é dispensado."]'::jsonb, '[]'::jsonb, '["Art. 66"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-77'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Oferecida a denúncia ou queixa, será reduzida a termo, entregando-se cópia ao acusado, que com ela ficará citado e cientificado da designação de dia e hora para a audiência de instrução e julgamento, da qual também tomarão ciência o Ministério Público, o ofendido, o responsável civil e seus advogados. Se o acusado não estiver presente, será citado na forma dos arts. 66 e 68 e deverá trazer suas testemunhas ou requerer a intimação no mínimo cinco dias antes da audiência. O ofendido e o responsável civil ausentes serão intimados, e as testemunhas arroladas também.', '["Denúncia ou queixa reduzida a termo.","Acusado presente fica citado com a entrega da cópia.","Testemunhas trazidas ou intimação requerida cinco dias antes.","Intimação do ofendido, do responsável civil e das testemunhas."]'::jsonb, '["Citação na própria audiência, com entrega de cópia."]'::jsonb, 'O acusado presente recebe a cópia da denúncia e fica citado.', '["Assertiva que exige nova citação por mandado do acusado presente erra: ele fica citado com a cópia."]'::jsonb, '[]'::jsonb, '["Art. 77"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-78'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No dia e hora designados para a audiência de instrução e julgamento, se na fase preliminar não tiver havido possibilidade de tentativa de conciliação e de oferecimento de proposta pelo Ministério Público, proceder-se-á nos termos dos arts. 72, 73, 74 e 75 da Lei.', '["Se a fase preliminar não ocorreu, repete-se na audiência de instrução a conciliação e a proposta."]'::jsonb, '["Garante a oportunidade de composição e transação."]'::jsonb, 'Se o autor não foi localizado antes, a transação é tentada na audiência de instrução.', '["Assertiva que dispensa a tentativa de conciliação na audiência de instrução quando não houve fase preliminar erra."]'::jsonb, '[]'::jsonb, '["Arts. 72 a 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-79'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum ato será adiado, determinando o Juiz, quando imprescindível, a condução coercitiva de quem deva comparecer.', '["Nenhum ato é adiado.","Condução coercitiva quando imprescindível."]'::jsonb, '["Vedado o adiamento."]'::jsonb, 'O juiz manda conduzir coercitivamente a testemunha faltosa em vez de adiar.', '["Assertiva que permite o adiamento livre dos atos erra: nenhum ato será adiado."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-80'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aberta a audiência, será dada a palavra ao defensor para responder à acusação, após o que o Juiz receberá, ou não, a denúncia ou queixa; havendo recebimento, serão ouvidas a vítima e as testemunhas de acusação e defesa, interrogando-se a seguir o acusado, passando-se aos debates orais e à sentença. Todas as provas serão produzidas na audiência, podendo o juiz limitar ou excluir as excessivas, impertinentes ou protelatórias. Durante a audiência, todos devem respeitar a dignidade da vítima, sob pena de responsabilização civil, penal e administrativa, vedadas manifestações sobre circunstâncias alheias aos fatos e linguagem ou material que ofendam a dignidade da vítima ou de testemunhas. Será lavrado termo, assinado pelo juiz e pelas partes, e a sentença dispensará o relatório.', '["Defesa antes do recebimento da denúncia.","Oitiva da vítima, testemunhas e interrogatório do acusado ao final.","Debates orais e sentença na própria audiência.","Respeito à dignidade da vítima.","Sentença sem relatório."]'::jsonb, '["ATUALIZAÇÃO: §1º-A incluído pela Lei nº 14.245, de 2021 (dignidade da vítima nas audiências).","O interrogatório é o ÚLTIMO ato de instrução."]'::jsonb, 'O juiz impede o advogado de usar linguagem ofensiva contra a vítima.', '["Assertiva que inicia a audiência com o interrogatório do acusado erra: o interrogatório vem depois da prova."]'::jsonb, '[]'::jsonb, '["Art. 78"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-81'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Da decisão de rejeição da denúncia ou queixa e da sentença caberá apelação, que poderá ser julgada por turma composta de três juízes em exercício no primeiro grau, reunidos na sede do Juizado. A apelação será interposta no prazo de dez dias, contados da ciência da sentença, por petição escrita com razões e pedido. O recorrido será intimado para responder por escrito em dez dias. As partes poderão requerer a transcrição da gravação. As partes serão intimadas da data do julgamento pela imprensa. Se a sentença for confirmada pelos próprios fundamentos, a súmula do julgamento servirá de acórdão.', '["Apelação contra a rejeição da denúncia e contra a sentença.","Turma de três juízes de primeiro grau.","Prazo de dez dias.","Resposta em dez dias.","Súmula como acórdão."]'::jsonb, '["Apelação em DEZ dias (no processo penal comum seriam cinco).","Julgada por turma recursal."]'::jsonb, 'O Ministério Público apela da rejeição da denúncia em dez dias.', '["Assertiva que fixa em cinco dias o prazo da apelação no Juizado Criminal erra: são dez dias."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-82'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cabem embargos de declaração quando, em sentença ou acórdão, houver obscuridade, contradição ou omissão. Serão opostos por escrito ou oralmente, no prazo de cinco dias, contados da ciência da decisão, e interrompem o prazo para a interposição de recurso. Os erros materiais podem ser corrigidos de ofício.', '["Embargos por obscuridade, contradição ou omissão.","Escritos ou orais, em cinco dias.","Interrompem o prazo do recurso.","Erros materiais corrigíveis de ofício."]'::jsonb, '["ATUALIZAÇÃO: o §2º (interrupção do prazo) foi alterado por lei posterior.","Interrompem (não suspendem) o prazo."]'::jsonb, 'A parte embarga oralmente de uma omissão na sentença.', '["Assertiva que fixa em dois dias o prazo dos embargos erra: são cinco."]'::jsonb, '[]'::jsonb, '["Art. 49"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-83'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicada exclusivamente pena de multa, seu cumprimento far-se-á mediante pagamento na Secretaria do Juizado. Efetuado o pagamento, o Juiz declarará extinta a punibilidade, determinando que a condenação não fique constando dos registros criminais, exceto para fins de requisição judicial.', '["Multa paga na Secretaria.","Pagamento extingue a punibilidade.","Sem registro criminal, exceto requisição judicial."]'::jsonb, '["Pagamento extingue a punibilidade."]'::jsonb, 'O autor paga a multa na Secretaria e o processo é extinto.', '["Assertiva que mantém a condenação nos registros criminais após o pagamento erra."]'::jsonb, '[]'::jsonb, '["Art. 85"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-84'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

