select u.id, u.content_sha256, 'Não efetuado o pagamento de multa, será feita a conversão em pena privativa da liberdade, ou restritiva de direitos, nos termos previstos em lei.', '["Conversão da multa não paga em pena privativa de liberdade ou restritiva de direitos."]'::jsonb, '["ATUALIZAÇÃO: a conversão da multa em prisão foi vedada por lei posterior no Código Penal; verifique a aplicação."]'::jsonb, 'A regra original previa converter a multa não paga em pena alternativa.', '["Assertiva que mantém hoje a conversão da multa em prisão sem ressalvas erra: houve alteração legislativa."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
