on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei entra em vigor no prazo de sessenta dias após a sua publicação.', '["Vacatio legis de sessenta dias."]'::jsonb, '["Sessenta dias de vacatio legis."]'::jsonb, 'A Lei só passou a valer sessenta dias depois de publicada.', '["Assertiva que prevê vigência imediata erra: são sessenta dias."]'::jsonb, '[]'::jsonb, '["Art. 97"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-96'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ficam revogadas a Lei nº 4.611, de 2 de abril de 1965 e a Lei nº 7.244, de 7 de novembro de 1984, que tratava dos Juizados de Pequenas Causas.', '["Revoga a lei do rito sumaríssimo e a lei dos Juizados de Pequenas Causas."]'::jsonb, '["Dispositivo de revogação."]'::jsonb, 'Os Juizados Especiais substituíram os antigos Juizados de Pequenas Causas.', '["Assertiva que mantém em vigor a lei dos Juizados de Pequenas Causas erra: foi revogada."]'::jsonb, '[]'::jsonb, '["Art. 96"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-97'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();
